import{_ as a,o as t,c as i,ag as n}from"./chunks/framework.BpToWd9i.js";const u=JSON.parse('{"title":"Contributing to Documentation","description":"","frontmatter":{"github_branch":"main"},"headers":[],"relativePath":"en/cpp/contributing/documentation.md","filePath":"en/cpp/contributing/documentation.md"}'),r={name:"en/cpp/contributing/documentation.md"};function o(s,e,l,c,h,d){return t(),i("div",null,e[0]||(e[0]=[n(`<h1 id="contributing-to-documentation" tabindex="-1">Contributing to Documentation <a class="header-anchor" href="#contributing-to-documentation" aria-label="Permalink to &quot;Contributing to Documentation&quot;">​</a></h1><p>Making quick fixes to existing text or raising issues is very easy. If you want to help, <a href="./../../#getting-help">get in touch</a>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>You will need a <a href="https://github.com/" target="_blank" rel="noreferrer">Github</a> login to make and submit changes to this guide.</p></div><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>This guide is written in <a href="https://vitepress.dev/guide/markdown" target="_blank" rel="noreferrer">markdown</a> and stored in the Github <a href="https://github.com/mavlink/MAVSDK" target="_blank" rel="noreferrer">mavlink/MAVSDK</a> repository under the <code>docs/</code> folder.</p><p>The <a href="./../api_reference/">API Reference</a> section is compiled from source code into markdown using a <a href="#api-reference">separate toolchain</a> and then checked in. Updates to the reference should be made in the <a href="https://github.com/mavlink/MAVSDK" target="_blank" rel="noreferrer">source code</a> (see <a href="#api-reference">API Reference</a> below for more information).</p><p>The guide is licensed under <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noreferrer">CC BY 4.0</a> - if you make any changes then they will be made available under the same license.</p><h2 id="making-a-quick-fix" tabindex="-1">Making a Quick Fix <a class="header-anchor" href="#making-a-quick-fix" aria-label="Permalink to &quot;Making a Quick Fix&quot;">​</a></h2><p>Simple fixes to an existing page can be made directly on Github:</p><ol><li>Navigate to the relevant file in the <a href="https://github.com/mavlink/MAVSDK/tree/main/docs/en" target="_blank" rel="noreferrer">docs/en/</a> folder.</li><li>Click the pencil (edit) icon to open the file editor.</li><li>Make the required changes.</li><li>At the bottom of the page, enter a commit message and select <strong>Create a new branch</strong> to open a pull request.</li></ol><h2 id="raising-an-issue" tabindex="-1">Raising an Issue <a class="header-anchor" href="#raising-an-issue" aria-label="Permalink to &quot;Raising an Issue&quot;">​</a></h2><p>To raise an issue against the documentation, open a <a href="https://github.com/mavlink/MAVSDK/issues" target="_blank" rel="noreferrer">Github issue</a> and include the page URL and a description of the problem.</p><h2 id="building-the-docs-locally" tabindex="-1">Building the Docs Locally <a class="header-anchor" href="#building-the-docs-locally" aria-label="Permalink to &quot;Building the Docs Locally&quot;">​</a></h2><p>The docs use <a href="https://vitepress.dev/" target="_blank" rel="noreferrer">VitePress</a>. To build and preview locally:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>This starts a local dev server at <code>http://localhost:5173</code>.</p><h2 id="api-reference" tabindex="-1">API Reference <a class="header-anchor" href="#api-reference" aria-label="Permalink to &quot;API Reference&quot;">​</a></h2><p>The C++ public header files are annotated using docstrings using <a href="https://www.doxygen.nl/manual/index.html" target="_blank" rel="noreferrer">Doxygen</a> syntax. You can extract the documentation to markdown files (one per class) on macOS or Linux using the instructions in <a href="./../guide/build_docs.html">Build API Reference Documentation</a>.</p><p>In order to include new API reference in the documentation:</p><ul><li>Copy the generated files into the <a href="https://github.com/mavlink/MAVSDK/tree/main/docs/en/cpp/api_reference" target="_blank" rel="noreferrer">docs/en/cpp/api_reference</a> folder</li><li><em>New</em> APIs should be added to the appropriate sections in <a href="https://github.com/mavlink/MAVSDK/tree/main/docs/en/SUMMARY.md" target="_blank" rel="noreferrer">docs/en/SUMMARY.md</a> and <a href="https://github.com/mavlink/MAVSDK/tree/main/docs/en/cpp/api_reference/index.md" target="_blank" rel="noreferrer">docs/en/cpp/api_reference/index.md</a>.</li></ul>`,20)]))}const m=a(r,[["render",o]]);export{u as __pageData,m as default};
